import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

const App = () => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // --- STYLES ---
  const containerStyle = {
    backgroundColor: '#050505',
    color: 'white',
    minHeight: '100vh',
    fontFamily: "'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
    overflow: 'hidden',
    position: 'relative',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    padding: '40px'
  };

  const glowCursor = {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    pointerEvents: 'none',
    zIndex: 1,
    background: `radial-gradient(600px at ${mousePos.x}px ${mousePos.y}px, rgba(121, 40, 202, 0.2), transparent 80%)`
  };

  const titleStyle = {
    fontSize: '5rem',
    fontWeight: '900',
    textAlign: 'center',
    marginTop: '100px',
    background: 'linear-gradient(90deg, #FF0080, #7928CA, #00DFD8)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    letterSpacing: '-2px'
  };

  const cardContainer = {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
    gap: '30px',
    width: '100%',
    maxWidth: '1100px',
    marginTop: '60px',
    zIndex: 10
  };

  const cardStyle = {
    background: 'rgba(255, 255, 255, 0.05)',
    backdropFilter: 'blur(15px)',
    border: '1px solid rgba(255, 255, 255, 0.1)',
    borderRadius: '24px',
    padding: '40px',
    textAlign: 'left',
    transition: 'all 0.3s ease'
  };

  return (
    <div style={containerStyle}>
      {/* Animated Glow Background */}
      <div style={glowCursor} />

      {/* Hero Section */}
      <motion.div 
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
        style={{ zIndex: 10 }}
      >
        <h1 style={titleStyle}>VIBRANT RGBRO</h1>
        <p style={{ color: '#888', fontSize: '1.2rem', textAlign: 'center' }}>
          Premium • Professional • Aesthetic
        </p>
      </motion.div>

      {/* Grid Sections */}
      <div style={cardContainer}>
        {[
          { name: "Achievements", color: "#FF0080" },
          { name: "Memories", color: "#7928CA" },
          { name: "Events", color: "#00DFD8" }
        ].map((item, index) => (
          <motion.div
            key={index}
            whileHover={{ scale: 1.05, border: `1px solid ${item.color}` }}
            style={cardStyle}
          >
            <div style={{ 
              width: '40px', 
              height: '40px', 
              backgroundColor: item.color, 
              borderRadius: '50%', 
              marginBottom: '20px',
              boxShadow: `0 0 20px ${item.color}`
            }} />
            <h2 style={{ fontSize: '1.8rem', marginBottom: '10px' }}>{item.name}</h2>
            <p style={{ color: '#aaa', lineHeight: '1.6' }}>
              Custom unique landing page redesign with professional cursor and animations.
            </p>
          </motion.div>
        ))}
      </div>

      {/* Floating Background Orbs */}
      <div style={{
        position: 'absolute',
        top: '-100px',
        right: '-100px',
        width: '400px',
        height: '400px',
        background: 'rgba(121, 40, 202, 0.15)',
        filter: 'blur(100px)',
        borderRadius: '50%'
      }} />
    </div>
  );
};

export default App;
